// DecodeRetryRequest returns a decoder for requests sent to the notifications
// retry endpoint.
func DecodeRetryRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*notifications.RetryPayload, error) {
	return func(r *http.Request) (*notifications.RetryPayload, error) {
		var payload *notifications.RetryPayload
		var (
			id     int64
			cookie string
			err    error

			params = mux.Vars(r)
		)
		{
			idRaw := params["id"]
			v, err2 := strconv.ParseInt(idRaw, 10, 64)
			if err2 != nil {
				err = goa.MergeErrors(err, goa.InvalidFieldTypeError("id", idRaw, "integer"))
			}
			id = v
		}
		if id < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("id", id, 1, true))
		}
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewRetryPayload(id, cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

