// EncodeTestResponse returns an encoder for responses returned by the
// notifications test endpoint.
func EncodeTestResponse(encoder func(context.Context, http.ResponseWriter) goahttp.Encoder) func(context.Context, http.ResponseWriter, any) error {
	return func(ctx context.Context, w http.ResponseWriter, v any) error {
		res, _ := v.(*notifications.TestResult)
		enc := encoder(ctx, w)
		body := NewTestResponseBody(res)
		w.WriteHeader(http.StatusOK)
		return enc.Encode(body)
	}
}

// DecodeTestRequest returns a decoder for requests sent to the notifications
// test endpoint.
func DecodeTestRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*notifications.TestPayload, error) {
	return func(r *http.Request) (*notifications.TestPayload, error) {
		var payload *notifications.TestPayload
		var (
			body TestRequestBody
			err  error
		)
		err = decoder(r).Decode(&body)
		if err != nil {
			if errors.Is(err, io.EOF) {
				return payload, goa.MissingPayloadError()
			}
			var gerr *goa.ServiceError
			if errors.As(err, &gerr) {
				return payload, gerr
			}
			return payload, goa.DecodePayloadError(err.Error())
		}
		err = ValidateTestRequestBody(&body)
		if err != nil {
			return payload, err
		}

		var (
			cookie string
		)
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewTestPayload(&body, cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

