// marshalNotificationsSentNotificationToSentNotificationResponse builds a
// value of type *SentNotificationResponse from a value of type
// *notifications.SentNotification.
func marshalNotificationsSentNotificationToSentNotificationResponse(v *notifications.SentNotification) *SentNotificationResponse {
	res := &SentNotificationResponse{
		ID:             v.ID,
		Title:          v.Title,
		Markdown:       v.Markdown,
		RecipientCount: v.RecipientCount,
		CreatedAt:      v.CreatedAt,
	}
	if v.Attachments != nil {
		res.Attachments = make([]*NotificationAttachment, len(v.Attachments))
		for i, val := range v.Attachments {
			if val == nil {
				res.Attachments[i] = nil
				continue
			}
			res.Attachments[i] = marshalNotificationsNotificationAttachmentToNotificationAttachment(val)
		}
	} else {
		res.Attachments = []*NotificationAttachment{}
	}

	return res
}

